/*
 * heap.h -- CS 313 P2: a binary max-heap of ints (a priority queue).
 *
 * DO NOT EDIT THIS FILE. The autograder uses its own copy.
 *
 * The heap stores its keys in data[0 .. size-1], a heap array of fixed
 * length `capacity`. The capacity is set at creation and never changes.
 *
 * Indexing: the root is at index 0 (C arrays start at 0). For index i:
 *     parent(i) = (i - 1) / 2      left(i) = 2i + 1      right(i) = 2i + 2
 * CLRS puts the root at 1 (parent i/2, children 2i and 2i+1). This is the
 * "root at 0" row of the course reference page.
 *
 * Max-heap property: data[parent(i)] >= data[i] for every i > 0.
 *
 * Tie rules (the tests check exact arrays, so follow these exactly):
 *   - Sift-up swaps a key with its parent only if the key is strictly
 *     greater than the parent.
 *   - Sift-down finds the largest of the node, its left child, and its
 *     right child, using strict > comparisons in that order. So the node
 *     stays put if it equals its largest child, and the LEFT child wins
 *     when the two children are equal. This is MAX-HEAPIFY in CLRS 6.2.
 *
 * Duplicate keys are allowed.
 *
 * Empty and full contract: heap_peek and heap_extract_max on an empty
 * heap return false and do not touch *out. heap_insert on a full heap
 * returns false and leaves the heap unchanged. No function prints,
 * exits, or crashes on these cases.
 */
#ifndef HEAP_H
#define HEAP_H

#include <stdbool.h>

typedef struct {
    int *data;         /* heap array of length capacity                */
    int size;          /* number of keys in the heap                   */
    int capacity;      /* length of data; fixed at creation            */
    long comparisons;  /* key comparisons made so far (optional; see
                          README, "Optional exploration")              */
} Heap;

/* Return a new empty heap that can hold up to `capacity` keys.
 * Return NULL if capacity < 1 or if memory allocation fails. */
Heap *heap_create(int capacity);

/* Free the data array and the Heap itself. Does nothing if h is NULL. */
void heap_destroy(Heap *h);

/* If the heap is full, return false and change nothing. Otherwise put
 * key at data[size], sift it up, and return true. O(lg n). */
bool heap_insert(Heap *h, int key);

/* If the heap is empty, return false and leave *out unchanged.
 * Otherwise store the largest key in *out and return true. O(1). */
bool heap_peek(const Heap *h, int *out);

/* If the heap is empty, return false and leave *out unchanged.
 * Otherwise store the largest key in *out, move the last key to the
 * root, shrink size by 1, sift the root down, and return true. O(lg n). */
bool heap_extract_max(Heap *h, int *out);

/* Return a new heap with the given capacity holding the n keys of a,
 * arranged by BUILD-MAX-HEAP (CLRS 6.3): copy a into data in order, then
 * sift down every non-leaf, from index n/2 - 1 down to 0. O(n).
 * The array a is not changed. If n is 0, a may be NULL; do not read it.
 * Return NULL if n < 0, capacity < 1, capacity < n, or memory
 * allocation fails. */
Heap *heap_build(const int *a, int n, int capacity);

/* Sort a[0 .. n-1] into increasing order in place with HEAPSORT
 * (CLRS 6.4): build a max-heap in a itself, then repeatedly swap a[0]
 * with the last key of the heap, shrink the heap by 1, and sift down
 * the new root. Use no second array. O(n lg n). Does nothing if n < 2. */
void heap_sort(int *a, int n);

/* Number of keys in the heap. */
int heap_size(const Heap *h);

/* Copy data[0 .. size-1] into out (which must have room for size ints)
 * and return size. The heap is not changed. The tests use this. */
int heap_to_array(const Heap *h, int *out);

/* Key comparisons made by this heap so far (optional; see README). */
long heap_comparisons(const Heap *h);

/* Print the heap for debugging: the array, then one line per level.
 * Already written for you in heap.c. */
void heap_print(const Heap *h);

#endif
